import{_ as e,c as t,o as a,a4 as o}from"./chunks/framework.ttppV29E.js";const i="/assets/tree-view-filter.BZTVJXFl.png",s="/assets/tree-view-1.CQJVfDOJ.png",y=JSON.parse('{"title":"Repositories Tree View","description":"","frontmatter":{},"headers":[],"relativePath":"docs/using-the-test-editor/repositories-tree-view.md","filePath":"docs/using-the-test-editor/repositories-tree-view.md","lastUpdated":1792486760000}'),r={name:"docs/using-the-test-editor/repositories-tree-view.md"},l=o('<h1 id="repositories-tree-view" tabindex="-1">Repositories Tree View <a class="header-anchor" href="#repositories-tree-view" aria-label="Permalink to &quot;Repositories Tree View&quot;">​</a></h1><p>The <strong>Repositories</strong> panel on the left-hand side shows your repository hierarchy and lets you manage folders, Test Sets, feature files, step definitions, and payloads - all from a single tree view.</p><h2 id="tree-structure" tabindex="-1">Tree Structure <a class="header-anchor" href="#tree-structure" aria-label="Permalink to &quot;Tree Structure&quot;">​</a></h2><ul><li><strong>Folder</strong><br> A container for Test Sets or nested folders.</li><li><strong>Test Set</strong><br> A suite of related feature files and step definitions.</li><li><strong>Feature File</strong><br> A <code>.feature</code> file containing scenarios.</li><li><strong>Step File</strong><br> A reusable set of test commands.</li><li><strong>Payload</strong><br> (Test Set only) An XML or JSON payload used for AireGlu or AireFlow testing.</li><li><strong>Files</strong><br> (Test Set only) A folder of files a test can upload into a file upload control. It only appears once the Test Set has at least one file.</li></ul><h2 id="filtering-the-tree" tabindex="-1">Filtering the Tree <a class="header-anchor" href="#filtering-the-tree" aria-label="Permalink to &quot;Filtering the Tree&quot;">​</a></h2><p>On a large repository it can be quicker to filter the tree than to expand your way down to a file. Select the magnifying glass at the top of the <strong>Repositories</strong> panel to show the filter box, and type any part of the name you are looking for.</p><p><img src="'+i+'" alt="Filtering the tree"></p><ul><li>Matching is on <strong>names only</strong> - folders, Test Sets, feature and step files, payloads and uploaded files. It is not case-sensitive, and matches any part of a name, so <code>book</code> finds <code>rebooking.feature</code>.</li><li>Folders containing a match open automatically, so a file nested several levels down appears without any expanding.</li><li>Matching a folder or Test Set keeps everything inside it, so you can open it up and browse as usual - a quick way to narrow the tree to one area.</li><li>The file you have open stays open in the editor even when the filter hides it from the tree.</li><li>Select the magnifying glass again (or press <code>Esc</code>) to hide the box. <strong>While the box is hidden no filter is applied</strong>, and the tree returns to exactly the folders you had open before.</li></ul><h2 id="context-menu-actions" tabindex="-1">Context-Menu Actions <a class="header-anchor" href="#context-menu-actions" aria-label="Permalink to &quot;Context-Menu Actions&quot;">​</a></h2><p>Select the 3 dots on any node in the tree to perform the following actions:</p><p><img src="'+s+'" alt="Tree View"></p><h3 id="_1-add-folder" tabindex="-1">1. Add Folder <a class="header-anchor" href="#_1-add-folder" aria-label="Permalink to &quot;1. Add Folder&quot;">​</a></h3><p>Creates a new folder under the selected node.</p><ul><li>Use folders to keep your Test Sets organised.</li></ul><h3 id="_2-add-test-set" tabindex="-1">2. Add Test Set <a class="header-anchor" href="#_2-add-test-set" aria-label="Permalink to &quot;2. Add Test Set&quot;">​</a></h3><p>Adds a new Test Set under the selected folder. This option is only available when selecting a folder</p><ul><li>This will need to be configured (see <a href="/docs/using-the-test-editor/file-and-test-set-settings.html"><strong>File and Test Set Settings</strong></a>)</li></ul><h3 id="_3-add-feature-file" tabindex="-1">3. Add Feature File <a class="header-anchor" href="#_3-add-feature-file" aria-label="Permalink to &quot;3. Add Feature File&quot;">​</a></h3><p>Creates a new <code>.feature</code> file inside the selected Test Set.</p><h3 id="_4-add-step-file" tabindex="-1">4. Add Step File <a class="header-anchor" href="#_4-add-step-file" aria-label="Permalink to &quot;4. Add Step File&quot;">​</a></h3><p>Adds a new step-definition file alongside the selected feature folder.</p><h3 id="_5-delete" tabindex="-1">5. Delete <a class="header-anchor" href="#_5-delete" aria-label="Permalink to &quot;5. Delete&quot;">​</a></h3><p>Removes the selected node (folder, Test Set, feature file, step file, or payload).</p><ul><li>A confirmation prompt will appear before deletion.</li></ul><h2 id="test-set-specific-actions" tabindex="-1">Test-Set-Specific Actions <a class="header-anchor" href="#test-set-specific-actions" aria-label="Permalink to &quot;Test-Set-Specific Actions&quot;">​</a></h2><p>When you select a <strong>Test Set</strong> node, two additional options appear in the context menu:</p><h3 id="•-add-aireglu-payload" tabindex="-1">• Add AireGlu Payload <a class="header-anchor" href="#•-add-aireglu-payload" aria-label="Permalink to &quot;• Add AireGlu Payload&quot;">​</a></h3><p>Creates a new payload template file in <code>AireGluPayloads/</code>.</p><ul><li>Use this for testing API-driven flows against your AireGlu instance.</li></ul><h3 id="•-add-aireflow-payload" tabindex="-1">• Add AireFlow Payload <a class="header-anchor" href="#•-add-aireflow-payload" aria-label="Permalink to &quot;• Add AireFlow Payload&quot;">​</a></h3><p>Creates a new payload template file in <code>AireFlowPayloads/</code>.</p><ul><li>Use this for triggering workflows or events in AireFlow.</li></ul><h3 id="•-add-file" tabindex="-1">• Add File <a class="header-anchor" href="#•-add-file" aria-label="Permalink to &quot;• Add File&quot;">​</a></h3><p>Chooses a file from your computer and adds it to the Test Set&#39;s <code>Files/</code> folder, for a test to upload into a file upload control (see <a href="/docs/command-library/aireform-commands.html#file-uploads"><strong>AireForm Commands</strong></a>).</p><ul><li>This action is on both the <strong>Test Set</strong> and the <strong>Files</strong> node, because <code>Files</code> only exists once the Test Set has a file in it.</li><li>Selecting a file previews it: images are shown, and text-based files such as <code>.json</code>, <code>.xml</code> and <code>.txt</code> open read-only. To change a file&#39;s contents, delete the old one and add it again.</li><li>Rename a file the same way as any other - select it and edit <strong>File name</strong> in the settings panel.</li><li>There is a maximum file size and a list of allowed file types, both set by your administrator. Runnable files are never allowed. A file that is too large or of the wrong type is rejected as soon as you choose it.</li></ul><h2 id="saving-changes" tabindex="-1">Saving Changes <a class="header-anchor" href="#saving-changes" aria-label="Permalink to &quot;Saving Changes&quot;">​</a></h2><p>Once you’ve finished editing the tree view, click <strong>Save Changes</strong> (or <strong>Reset</strong> to revert changes) at the bottom of the <strong>Test Editor</strong>, you will be prompted for a commit message before saving to summarise the changes.</p>',37),n=[l];function d(h,c,f,p,u,g){return a(),t("div",null,n)}const b=e(r,[["render",d]]);export{y as __pageData,b as default};
